function GoldDivider() {
  return (
    <div className="flex items-center gap-2 mt-1">
      <span style={{ width: 26, height: 1, background: PALETTE.gold }} />
      <span style={{ color: PALETTE.gold, fontSize: 10 }}>✦</span>
      <span style={{ width: 26, height: 1, background: PALETTE.gold }} />
    </div>
  );
}

function HeartCup() {
  return (
    <svg width="46" height="40" viewBox="0 0 46 40">
      <path
        d="M23 38 C10 29, 2 21, 2 12.5 C2 5.6, 7.4 1, 13.6 1 C18 1, 21.2 3.4, 23 6.6 C24.8 3.4, 28 1, 32.4 1 C38.6 1, 44 5.6, 44 12.5 C44 21, 36 29, 23 38 Z"
        fill="none"
        stroke={PALETTE.roseDeep}
        strokeWidth="1.4"
      />
      <ellipse cx="23" cy="21" rx="9" ry="6" fill="#faf7f2" stroke={PALETTE.gold} strokeWidth="0.8" />
      <circle cx="19" cy="18.5" r="2.1" fill={PALETTE.rose} />
      <circle cx="24" cy="17" r="2.3" fill={PALETTE.sageLight} />
      <circle cx="27.5" cy="19.5" r="1.8" fill="#e0a23a" />
      <circle cx="21.5" cy="21" r="1.6" fill={PALETTE.sage} />
    </svg>
  );
}

function CornerFloral({ corner = "tl", flip = false }) {
  const style = {
    tl: { top: 0, left: 0 },
    br: { bottom: 0, right: 0 },
  }[corner];
  return (
    <svg
      width="120"
      height="150"
      viewBox="0 0 120 150"
      className="absolute pointer-events-none opacity-80 z-0"
      style={{
        ...style,
        transform: flip ? "rotate(180deg)" : "none",
      }}
    >
      <path
        d="M8 4 C 30 20, 20 60, 40 90 C 55 112, 45 135, 30 148"
        fill="none"
        stroke={PALETTE.sageLight}
        strokeWidth="2"
        opacity="0.6"
      />
      {[18, 42, 68, 96].map((y, i) => (
        <ellipse
          key={i}
          cx={16 + (i % 2) * 10}
          cy={y}
          rx="9"
          ry="4.5"
          fill={PALETTE.sageLight}
          opacity="0.55"
          transform={`rotate(${-30 + i * 18} ${16 + (i % 2) * 10} ${y})`}
        />
      ))}
      {[
        [22, 14],
        [30, 55],
      ].map(([cx, cy], i) => (
        <g key={i} opacity="0.85">
          {[0, 60, 120, 180, 240, 300].map((rot) => (
            <ellipse
              key={rot}
              cx={cx}
              cy={cy}
              rx="7"
              ry="4"
              fill={PALETTE.rose}
              opacity="0.75"
              transform={`rotate(${rot} ${cx} ${cy})`}
            />
          ))}
          <circle cx={cx} cy={cy} r="2.6" fill={PALETTE.gold} />
        </g>
      ))}
    </svg>
  );
}
